css:
.fx-shim{text-align:center;display:grid;gap:1em;justify-items:center;max-width:900px}
.fx-shim .eye{font-size:.8em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}
.fx-shim h1{font-size:clamp(2.6em,7vw,5.2em);line-height:1.04;background:linear-gradient(90deg,var(--primary),var(--accent),var(--primary));background-size:200% auto;-webkit-background-clip:text;background-clip:text;color:transparent;animation:fxshim calc(6s/var(--speed)) linear infinite}
.fx-shim p{max-width:46ch;opacity:.68;font-size:1.15em}
@keyframes fxshim{to{background-position:-200% center}}
@media(prefers-reduced-motion:reduce){.fx-shim h1{animation:none}}
